class Person {
  constructor(name) {
    this._name = name;
  }
  set name(value) {
    if (typeof value === "string") {
      this._name = value;
    }
  }
  get name() {
    return this._name;
  }
}

let amy = new Person("Amy");
console.log(amy.name); // Amy

amy.name = 10;
console.log(amy.name); // Amy

amy.name = "Big";
console.log(amy.name); // Big
